// Downloadable resume editions. resume-editions.json is generated by
// `pnpm resumes` (scripts/resume/build_resumes.py) alongside the PDFs in
// public/resumes/ — don't edit it by hand.
import manifest from './resume-editions.json'
import type { Audience } from './resume'

export interface ResumeEdition {
  id: Audience
  label: string
  headline: string
  /** Site-relative URL of the PDF, served from public/resumes/. */
  file: string
  pages: number
}

export const editions = manifest.editions as ResumeEdition[]

/** SHA-256 of carlos-barajas-resume.md at generation time; a unit test compares it to the current file. */
export const editionsSourceSha256 = manifest.sourceSha256

/** "October 2026", from the ISO date the PDFs were generated (parsed as a local date, not UTC). */
export const editionsUpdated = (() => {
  const [year, month, day] = manifest.generated.split('-').map(Number)
  return new Date(year, month - 1, day).toLocaleDateString('en-US', {
    month: 'long',
    year: 'numeric',
  })
})()
